declare(strict_types=1);

namespace paygw_payway\external;

use core_external\external_api;
use core_external\external_function_parameters;
use core_external\external_value;
use core_external\external_single_structure;

/**
 * External function to process a PayWay single-use token and complete the payment.
 */
class process_payment extends external_api {

    /**
     * Returns description of method parameters.
     *
     * @return external_function_parameters
     */
    public static function execute_parameters(): external_function_parameters {
        return new external_function_parameters([
            'component' => new external_value(PARAM_COMPONENT, 'Component'),
            'paymentarea' => new external_value(PARAM_AREA, 'Payment area in the component'),
            'itemid' => new external_value(PARAM_INT, 'An identifier for payment area in the component'),
            'token' => new external_value(PARAM_RAW, 'The single-use token generated by payway.js'),
        ]);
    }

    /**
     * Processes the given single-use token and completes the payment.
     *
     * @param string $component
     * @param string $paymentarea
     * @param int $itemid
     * @param string $token
     * @return string[]
     */
    public static function execute(string $component, string $paymentarea, int $itemid, string $token): array {
        self::validate_parameters(self::execute_parameters(), [
            'component' => $component,
            'paymentarea' => $paymentarea,
            'itemid' => $itemid,
            'token' => $token,
        ]);

        // TODO: use the token to charge the card via the PayWay API and record the payment.
        return [
            'status' => 'ok',
        ];
    }

    /**
     * Returns description of method result value.
     *
     * @return external_single_structure
     */
    public static function execute_returns(): external_single_structure {
        return new external_single_structure([
            'status' => new external_value(PARAM_TEXT, 'Result status of the payment processing'),
        ]);
    }
}
